// Package listenertls supplies the certificate Janus serves on its own
// listener, for direct TLS:
//
//   - an issued certificate mounted as files (JANUS_TLS_CERT_PATH /
//     JANUS_TLS_KEY_PATH, typically a cert-manager Secret). The files are
//     re-read when they change, so a renewed certificate is served without
//     a restart.
//   - a self-signed certificate (JANUS_TLS_SELF_SIGNED), generated by Janus,
//     stored in the database with its private key encrypted, and therefore
//     the same on every replica. It is a stopgap for testing or while an
//     issued certificate is on its way: the proxy in front of Janus trusts
//     the downloaded certificate itself, so each regeneration means
//     reinstalling it there.
//
// A mounted certificate always takes precedence over a self-signed one.
package listenertls

import (
	"context"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/sha256"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/hex"
	"encoding/json"
	"encoding/pem"
	"errors"
	"fmt"
	"log/slog"
	"math/big"
	"net"
	"os"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

// Modes.
const (
	ModeNone       = "none"
	ModeMounted    = "mounted"
	ModeSelfSigned = "self_signed"
)

// ExpiryWarning is how far ahead the listener certificate is flagged.
const ExpiryWarning = 30 * 24 * time.Hour

// Info describes the certificate being served.
type Info struct {
	Mode        string    `json:"mode"`
	Subject     string    `json:"subject,omitempty"`
	Names       []string  `json:"names,omitempty"`
	SHA256      string    `json:"sha256,omitempty"`
	NotBefore   time.Time `json:"not_before,omitempty"`
	NotAfter    time.Time `json:"not_after,omitempty"`
	ExpiresSoon bool      `json:"expires_soon"`
	Expired     bool      `json:"expired"`
	Required    bool      `json:"required"`
	CertPath    string    `json:"cert_path,omitempty"`
	LastError   string    `json:"last_error,omitempty"`
	GeneratedAt time.Time `json:"generated_at,omitempty"`
	GeneratedBy string    `json:"generated_by,omitempty"`
}

// Stored is the persisted self-signed certificate (key encrypted).
type Stored struct {
	CertPEM     string    `json:"cert_pem"`
	KeyEnc      string    `json:"key_enc"`
	GeneratedAt time.Time `json:"generated_at"`
	GeneratedBy string    `json:"generated_by"`
}

// Persistence is how the self-signed certificate is loaded and saved.
type Persistence struct {
	Load    func(ctx context.Context) (*Stored, error) // (nil, nil) when none
	Save    func(ctx context.Context, s *Stored) error
	Encrypt func(string) (string, error)
	Decrypt func(string) (string, error)
}

// Options configure the provider.
type Options struct {
	CertPath, KeyPath string
	SelfSigned        bool
	Names             []string
	Days              int
	Required          bool
	Persist           Persistence
	Logger            *slog.Logger
	Now               func() time.Time
}

// Provider serves the current certificate through GetCertificate.
type Provider struct {
	opts Options

	cert    atomic.Pointer[tls.Certificate]
	mu      sync.Mutex
	info    Info
	modTime time.Time
	checked time.Time
}

// New loads the certificate. It fails when a mounted pair cannot be read,
// or when the self-signed certificate can be neither loaded nor generated,
// so a broken configuration stops startup.
func New(ctx context.Context, o Options) (*Provider, error) {
	if o.Logger == nil {
		o.Logger = slog.Default()
	}
	if o.Now == nil {
		o.Now = time.Now
	}
	if o.Days <= 0 {
		o.Days = 365
	}
	p := &Provider{opts: o}
	switch {
	case o.CertPath != "":
		if err := p.loadMounted(); err != nil {
			return nil, err
		}
	case o.SelfSigned:
		if err := p.loadOrGenerate(ctx); err != nil {
			return nil, err
		}
	default:
		p.info = Info{Mode: ModeNone, Required: o.Required}
	}
	return p, nil
}

// Enabled reports whether Janus serves TLS itself.
func (p *Provider) Enabled() bool { return p != nil && p.info.Mode != ModeNone }

// TLSConfig is the listener's server config.
func (p *Provider) TLSConfig() *tls.Config {
	return &tls.Config{MinVersion: tls.VersionTLS12, GetCertificate: p.GetCertificate}
}

// GetCertificate implements tls.Config.GetCertificate. A mounted
// certificate is re-read at most every 10 seconds when its file changed.
func (p *Provider) GetCertificate(*tls.ClientHelloInfo) (*tls.Certificate, error) {
	if p.opts.CertPath != "" {
		p.maybeReloadMounted()
	}
	c := p.cert.Load()
	if c == nil {
		return nil, errors.New("no listener certificate")
	}
	return c, nil
}

func (p *Provider) maybeReloadMounted() {
	p.mu.Lock()
	if time.Since(p.checked) < 10*time.Second {
		p.mu.Unlock()
		return
	}
	p.checked = time.Now()
	last := p.modTime
	p.mu.Unlock()
	st, err := os.Stat(p.opts.CertPath)
	if err != nil || !st.ModTime().After(last) {
		return
	}
	if err := p.loadMounted(); err != nil {
		// Keep serving the previous certificate.
		p.mu.Lock()
		p.info.LastError = err.Error()
		p.mu.Unlock()
		p.opts.Logger.Warn("listener certificate reload failed; still serving the previous one", "error", err.Error())
		return
	}
	p.opts.Logger.Info("listener certificate reloaded", "path", p.opts.CertPath, "not_after", p.Info().NotAfter)
}

func (p *Provider) loadMounted() error {
	pair, err := tls.LoadX509KeyPair(p.opts.CertPath, p.opts.KeyPath)
	if err != nil {
		return fmt.Errorf("load JANUS_TLS_CERT_PATH/JANUS_TLS_KEY_PATH: %w", err)
	}
	leaf, err := x509.ParseCertificate(pair.Certificate[0])
	if err != nil {
		return err
	}
	pair.Leaf = leaf
	st, _ := os.Stat(p.opts.CertPath)
	p.mu.Lock()
	defer p.mu.Unlock()
	p.cert.Store(&pair)
	p.info = p.describe(ModeMounted, leaf)
	p.info.CertPath = p.opts.CertPath
	if st != nil {
		p.modTime = st.ModTime()
	}
	return nil
}

func (p *Provider) describe(mode string, leaf *x509.Certificate) Info {
	sum := sha256.Sum256(leaf.Raw)
	names := append([]string{}, leaf.DNSNames...)
	for _, ip := range leaf.IPAddresses {
		names = append(names, ip.String())
	}
	now := p.opts.Now()
	return Info{Mode: mode, Subject: leaf.Subject.String(), Names: names, SHA256: hex.EncodeToString(sum[:]),
		NotBefore: leaf.NotBefore, NotAfter: leaf.NotAfter, Required: p.opts.Required,
		Expired: now.After(leaf.NotAfter), ExpiresSoon: !now.After(leaf.NotAfter) && leaf.NotAfter.Sub(now) < ExpiryWarning}
}

func (p *Provider) loadOrGenerate(ctx context.Context) error {
	if p.opts.Persist.Load == nil {
		return errors.New("self-signed listener certificate: no storage configured")
	}
	stored, err := p.opts.Persist.Load(ctx)
	if err != nil {
		return fmt.Errorf("load self-signed listener certificate: %w", err)
	}
	if stored != nil {
		if err := p.useStored(stored); err == nil {
			return nil
		} else {
			p.opts.Logger.Warn("stored self-signed listener certificate unusable; generating a new one", "error", err.Error())
		}
	}
	_, err = p.Regenerate(ctx, nil, p.opts.Days, "startup")
	return err
}

// Refresh re-reads the stored self-signed certificate (another replica may
// have regenerated it). No-op in other modes.
func (p *Provider) Refresh(ctx context.Context) error {
	if !p.opts.SelfSigned || p.opts.CertPath != "" {
		return nil
	}
	stored, err := p.opts.Persist.Load(ctx)
	if err != nil || stored == nil {
		return err
	}
	if c := p.cert.Load(); c != nil && c.Leaf != nil {
		if block, _ := pem.Decode([]byte(stored.CertPEM)); block != nil && string(block.Bytes) == string(c.Leaf.Raw) {
			return nil
		}
	}
	return p.useStored(stored)
}

func (p *Provider) useStored(s *Stored) error {
	keyPEM, err := p.opts.Persist.Decrypt(s.KeyEnc)
	if err != nil {
		return fmt.Errorf("decrypt key: %w", err)
	}
	pair, err := tls.X509KeyPair([]byte(s.CertPEM), []byte(keyPEM))
	if err != nil {
		return err
	}
	leaf, err := x509.ParseCertificate(pair.Certificate[0])
	if err != nil {
		return err
	}
	pair.Leaf = leaf
	p.mu.Lock()
	defer p.mu.Unlock()
	p.cert.Store(&pair)
	p.info = p.describe(ModeSelfSigned, leaf)
	p.info.GeneratedAt, p.info.GeneratedBy = s.GeneratedAt, s.GeneratedBy
	return nil
}

// ErrNotSelfSigned is returned by Regenerate outside self-signed mode.
var ErrNotSelfSigned = errors.New("the listener is not using a self-signed certificate")

// Regenerate creates a new self-signed certificate, stores it and serves
// it at once. names nil keeps the configured names; days 0 keeps the
// configured lifetime.
func (p *Provider) Regenerate(ctx context.Context, names []string, days int, by string) (Info, error) {
	if !p.opts.SelfSigned || p.opts.CertPath != "" {
		return Info{}, ErrNotSelfSigned
	}
	if len(names) == 0 {
		names = p.opts.Names
	}
	if len(names) == 0 {
		names = []string{"localhost", "127.0.0.1"}
	}
	if days <= 0 {
		days = p.opts.Days
	}
	if days > 1095 {
		return Info{}, errors.New("a self-signed certificate may be valid for at most 1095 days")
	}
	certPEM, keyPEM, err := Generate(names, time.Duration(days)*24*time.Hour, p.opts.Now())
	if err != nil {
		return Info{}, err
	}
	enc, err := p.opts.Persist.Encrypt(keyPEM)
	if err != nil {
		return Info{}, err
	}
	s := &Stored{CertPEM: certPEM, KeyEnc: enc, GeneratedAt: p.opts.Now().UTC(), GeneratedBy: by}
	if err := p.opts.Persist.Save(ctx, s); err != nil {
		return Info{}, fmt.Errorf("save self-signed listener certificate: %w", err)
	}
	if err := p.useStored(s); err != nil {
		return Info{}, err
	}
	p.opts.Logger.Info("self-signed listener certificate generated", "names", names, "days", days, "by", by)
	return p.Info(), nil
}

// CertificatePEM is the served certificate (public part only), for
// download into a proxy's trust store.
func (p *Provider) CertificatePEM() string {
	c := p.cert.Load()
	if c == nil {
		return ""
	}
	var b strings.Builder
	for _, der := range c.Certificate {
		_ = pem.Encode(&b, &pem.Block{Type: "CERTIFICATE", Bytes: der})
	}
	return b.String()
}

// Info returns what is being served.
func (p *Provider) Info() Info {
	if p == nil {
		return Info{Mode: ModeNone}
	}
	p.mu.Lock()
	defer p.mu.Unlock()
	out := p.info
	if c := p.cert.Load(); c != nil && c.Leaf != nil {
		now := p.opts.Now()
		out.Expired = now.After(c.Leaf.NotAfter)
		out.ExpiresSoon = !out.Expired && c.Leaf.NotAfter.Sub(now) < ExpiryWarning
	}
	return out
}

// Generate makes a self-signed ECDSA P-256 certificate for names (DNS names
// or IP addresses), usable for server authentication, valid for life from
// a minute ago.
func Generate(names []string, life time.Duration, now time.Time) (certPEM, keyPEM string, err error) {
	if len(names) == 0 {
		return "", "", errors.New("at least one name is required")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return "", "", err
	}
	serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 127))
	if err != nil {
		return "", "", err
	}
	tmpl := &x509.Certificate{
		SerialNumber: serial,
		Subject:      pkix.Name{CommonName: names[0], Organization: []string{"Janus (self-signed)"}},
		NotBefore:    now.Add(-time.Minute), NotAfter: now.Add(life),
		KeyUsage:              x509.KeyUsageDigitalSignature,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		BasicConstraintsValid: true,
	}
	for _, n := range names {
		n = strings.TrimSpace(n)
		if n == "" {
			continue
		}
		if ip := net.ParseIP(strings.Trim(n, "[]")); ip != nil {
			tmpl.IPAddresses = append(tmpl.IPAddresses, ip)
		} else if validDNSName(n) {
			tmpl.DNSNames = append(tmpl.DNSNames, strings.ToLower(n))
		} else {
			return "", "", fmt.Errorf("%q is not a valid DNS name or IP address", n)
		}
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		return "", "", err
	}
	kder, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return "", "", err
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})),
		string(pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: kder})), nil
}

func validDNSName(n string) bool {
	if len(n) == 0 || len(n) > 253 {
		return false
	}
	for i, label := range strings.Split(n, ".") {
		if label == "*" && i == 0 {
			continue
		}
		if label == "" || len(label) > 63 || label[0] == '-' || label[len(label)-1] == '-' {
			return false
		}
		for _, r := range label {
			if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '-') {
				return false
			}
		}
	}
	return true
}

// MarshalStored / UnmarshalStored encode the stored certificate for a
// system setting.
func MarshalStored(s *Stored) (string, error) {
	b, err := json.Marshal(s)
	return string(b), err
}

// UnmarshalStored decodes MarshalStored output.
func UnmarshalStored(raw string) (*Stored, error) {
	var s Stored
	if err := json.Unmarshal([]byte(raw), &s); err != nil {
		return nil, err
	}
	return &s, nil
}
